import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-cell-biology-organelles-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`Compare lysosomes and peroxisomes.`]: {
    question: r`A researcher isolates two organelle fractions. The enzymes of fraction 1 work best near pH 5 and break proteins and nucleic acids into monomers. Fraction 2 shortens a 26-carbon fatty acid and both makes and destroys H₂O₂. What are the fractions?`,
    options: [r`Fraction 1 is peroxisomes; fraction 2 is lysosomes`, r`Fraction 1 is lysosomes; fraction 2 is mitochondria`, r`Fraction 1 is proteasomes; fraction 2 is peroxisomes`, r`Fraction 1 is lysosomes; fraction 2 is peroxisomes`],
    correctAnswer: 3,
    explanation: r`Acid hydrolases that digest macromolecules mark lysosomes, while oxidation of very-long-chain fatty acids with H₂O₂ made and then removed by catalase marks peroxisomes. Swapping the two reverses the jobs. Mitochondria do not handle a 26-carbon fatty acid or make H₂O₂ this way, and proteasomes work at neutral pH and digest only proteins.`,
  },
  [r`What distinguishes prokaryotic from eukaryotic cells?`]: {
    question: r`A soil microbe has a single circular chromosome lying in the cytoplasm with no membrane around it, and its ribosomes are 70S. Which further finding is expected in this cell?`,
    options: [r`Linear chromosomes capped by long telomere repeats`, r`A nucleolus that assembles its ribosomal subunits`, r`Mitochondria but no endoplasmic reticulum at all`, r`No mitochondria or other membrane-bound organelles`],
    correctAnswer: 3,
    explanation: r`A nucleoid with circular DNA and 70S ribosomes identifies a prokaryote, and prokaryotes have no membrane-bound organelles. Mitochondria, linear chromosomes with telomeres and a nucleolus inside a nucleus are all features of eukaryotic cells.`,
  },
  [r`What is the function of the mitochondrion and why is it unusual?`]: {
    question: r`A drug blocks replication of the small circular DNA genomes inside human cells but leaves the nuclear chromosomes alone. After many cell divisions, which process fails first?`,
    options: [r`Protein glycosylation in the Golgi cisternae`, r`Oxidative phosphorylation on the inner membrane`, r`Hydrolytic digestion inside the lysosomes`, r`Glycolysis in the cytosol of the treated cells`],
    correctAnswer: 1,
    explanation: r`The only circular genome in a human cell is mitochondrial DNA, which encodes parts of the electron transport chain, so ATP production by oxidative phosphorylation is lost. Glycolysis, Golgi glycosylation and lysosomal digestion depend only on nuclear genes and on organelles with no DNA of their own.`,
  },
  [r`What is the role of the cytoskeleton components?`]: {
    question: r`An animal cell has just finished separating its chromosomes in anaphase when a drug that depolymerizes actin filaments is added. What is the most direct result?`,
    options: [r`The cilia lose their 9+2 axonemes and stop beating at once`, r`No cleavage furrow forms, leaving one cell with two nuclei`, r`The cell loses its tensile strength and tears into pieces`, r`The spindle falls apart, and the chromosomes drift back`],
    correctAnswer: 1,
    explanation: r`The cleavage furrow of cytokinesis is an actin (microfilament) ring, so without actin the cell cannot pinch in two and keeps both nuclei. The spindle and the 9+2 axoneme are built from microtubules, and tensile strength comes from intermediate filaments, so none of those is the direct target.`,
  },
  [r`What does the Golgi apparatus do?`]: {
    question: r`A vesicle that budded from the ER carries a newly made glycoprotein to the Golgi apparatus. Where does the vesicle fuse, and from where does the finished protein leave?`,
    options: [r`It fuses at the cis face, and the protein leaves from the cis face`, r`It fuses at the trans face, and the protein leaves from the trans face`, r`It fuses at the trans face, and the protein leaves from the cis face`, r`It fuses at the cis face, and the protein leaves from the trans face`],
    correctAnswer: 3,
    explanation: r`The Golgi is polarized: the cis face receives vesicles from the ER and the trans face ships sorted cargo out. Reversing the faces runs the assembly line backward, and using one face for both entry and exit ignores that cargo crosses the whole stack while it is modified.`,
  },
  [r`Distinguish rough vs. smooth endoplasmic reticulum.`]: {
    question: r`A skeletal muscle fiber starts a contraction by releasing a burst of stored Ca²⁺ into its cytosol. Which compartment held that Ca²⁺, and what else is the same organelle known for?`,
    options: [r`Smooth ER, which also makes lipids and steroids`, r`Rough ER, which also makes lipids and steroids`, r`Smooth ER, which also makes secreted proteins`, r`Rough ER, which also makes secreted proteins`],
    correctAnswer: 0,
    explanation: r`The sarcoplasmic reticulum is specialized smooth ER, and smooth ER also carries out lipid and steroid synthesis and detoxification. Rough ER is the ribosome-studded form that makes secreted and membrane proteins, so the choices naming rough ER or giving smooth ER the protein-making job mix up the two.`,
  },
  [r`Trace a secreted protein from synthesis to release (which organelles, in order).`]: {
    question: r`A salivary gland cell makes the enzyme amylase and releases it into saliva. Which list gives the compartments an amylase molecule passes through, from first to last?`,
    options: [r`Rough ER, trans Golgi, cis Golgi, secretory vesicle`, r`Smooth ER, cis Golgi, trans Golgi, secretory vesicle`, r`Cis Golgi, rough ER, trans Golgi, secretory vesicle`, r`Rough ER, cis Golgi, trans Golgi, secretory vesicle`],
    correctAnswer: 3,
    explanation: r`A secreted protein is made and folded on the rough ER, enters the Golgi at the cis face, is sorted at the trans face and leaves in a secretory vesicle that fuses with the plasma membrane. The other lists run the Golgi backward, start at the smooth ER (which makes lipids, not secreted proteins), or put the Golgi before the ER.`,
  },
  [r`What does the nucleolus do, and what accumulates there?`]: {
    question: r`A stain specific for ribosomal RNA is applied to a nucleus and concentrates in one dense spot that has no membrane around it. What is being produced in that spot?`,
    options: [r`Messenger RNAs, spliced there before leaving the nucleus`, r`Nuclear lamins, assembled there into the lamina mesh`, r`Ribosomal subunits, built from rRNA transcribed there`, r`Finished proteins, translated there by 80S ribosomes`],
    correctAnswer: 2,
    explanation: r`A dense, non-membrane-bound nuclear region rich in rRNA is the nucleolus, where rRNA is transcribed and combined with ribosomal proteins into subunits. It is not where mRNA is processed or lamins assemble, and translation by complete ribosomes happens in the cytoplasm, not in the nucleolus.`,
  },
  [r`Proteins destined for secretion are synthesized on the {{c1::rough ER}}, then modified and sorted in the {{c2::Golgi apparatus}}.`]: {
    question: r`A liver cell secretes the glycoprotein transferrin, which carries complex sugar chains. Where was the polypeptide made, and where were its sugar chains finished and the protein sorted for export?`,
    options: [r`Made in the Golgi; finished and sorted on the rough ER`, r`Made on the smooth ER; finished and sorted in the Golgi`, r`Made on the rough ER; finished and sorted in lysosomes`, r`Made on the rough ER; finished and sorted in the Golgi`],
    correctAnswer: 3,
    explanation: r`Proteins destined for secretion are synthesized on the rough ER and then modified and sorted in the Golgi apparatus. Smooth ER has no ribosomes, the Golgi does not synthesize polypeptides, and lysosomes digest material instead of preparing it for export.`,
  },
  [r`Which organelle detoxifies drugs in liver cells?`]: {
    question: r`A liver cell line loses the function of one organelle and can no longer add hydroxyl groups to a lipid-soluble drug to make it water-soluble for excretion. Which organelle and which enzymes were lost?`,
    options: [r`Golgi, with its glycosyltransferase enzymes`, r`Rough ER, with its membrane-bound ribosomes`, r`Lysosome, with its acid hydrolase enzymes`, r`Smooth ER, with its cytochrome P450 enzymes`],
    correctAnswer: 3,
    explanation: r`Drug detoxification in hepatocytes is carried out by cytochrome P450 enzymes in the smooth ER membrane. Rough ER ribosomes make proteins, lysosomal hydrolases digest macromolecules, and Golgi glycosyltransferases add sugars to proteins, so none of them converts a lipid-soluble drug into an excretable form.`,
  },
  [r`Nuclear pores regulate:`]: {
    question: r`A histone protein is made in the cytosol and must reach chromatin, while a newly made mRNA must reach the ribosomes. Which statement describes how each crosses the nuclear envelope?`,
    options: [r`The histone enters and the mRNA exits, both through nuclear pores`, r`The histone enters through pores; the mRNA exits in budded vesicles`, r`The histone enters by vesicle fusion; the mRNA exits through pores`, r`The histone and the mRNA both diffuse across the envelope bilayers`],
    correctAnswer: 0,
    explanation: r`Nuclear pores are the route for both directions of traffic: proteins move in and RNA moves out through the same pores. The envelope does not exchange these molecules by vesicles, and large charged molecules such as proteins and RNA cannot diffuse through lipid bilayers.`,
  },
  [r`The nucleolus is the site of:`]: {
    question: r`Cells are treated with a compound that makes their nucleoli break apart. Which cellular product is the first to fall in supply?`,
    options: [r`New mRNA transcripts sent out to the cytosol`, r`New ribosomal subunits sent out to the cytosol`, r`New DNA strands made in S phase of the cycle`, r`New tRNAs charged with their amino acids`],
    correctAnswer: 1,
    explanation: r`The nucleolus is where rRNA is made and ribosomal subunits are assembled, so losing it cuts off the supply of new ribosomes first. mRNA transcription and DNA replication occur elsewhere in the nucleus, and tRNA charging is a cytosolic reaction.`,
  },
  [r`Which organelle is the site of protein synthesis?`]: {
    question: r`Hexokinase works in the cytosol, while insulin is secreted from the cell. Which ribosomes synthesize each protein?`,
    options: [r`Both on free ribosomes, with insulin sorted later by the Golgi`, r`Both on rough ER ribosomes, with hexokinase released later`, r`Hexokinase on rough ER ribosomes; insulin on free ribosomes`, r`Hexokinase on free ribosomes; insulin on rough ER ribosomes`],
    correctAnswer: 3,
    explanation: r`Free ribosomes make proteins that stay in the cytosol, and ribosomes bound to the rough ER make secreted and membrane proteins. Reversing the pair sends each protein to the wrong place, and a protein finished on a free ribosome never enters the ER or Golgi, just as a protein made into the ER lumen is not released back to the cytosol.`,
  },
  [r`Receptor-mediated endocytosis is characterized by:`]: {
    question: r`Cultured cells take up a labeled nutrient carrier present at a very low concentration. Uptake is specific to that carrier and levels off when more carrier is added. Where would an electron micrograph show the carrier as it enters?`,
    options: [r`In long pseudopods, wrapped around a particle`, r`In clathrin-coated pits, bound to its receptors`, r`In open ion channels, moving down a gradient`, r`In smooth membrane ruffles, dissolved in fluid`],
    correctAnswer: 1,
    explanation: r`Specific, saturable uptake of a dilute ligand is receptor-mediated endocytosis, which concentrates receptor-bound cargo in clathrin-coated pits. Fluid-phase uptake in ruffles is nonselective and does not saturate, pseudopods engulf large particles in phagocytosis, and channels carry ions, not protein carriers.`,
  },
  [r`Autophagy involves:`]: {
    question: r`During a long fast, liver cells lose many of their organelles yet keep their pool of free amino acids steady. Which process accounts for both observations?`,
    options: [r`Peroxisomes oxidizing the cell's own ribosomes`, r`Lysosomes expelling whole organelles from the cell`, r`Lysosomes digesting the cell's own organelles`, r`Proteasomes digesting endocytosed blood proteins`],
    correctAnswer: 2,
    explanation: r`Autophagy delivers the cell's own components to lysosomes, where they are broken down and the monomers are reused, which explains fewer organelles with a maintained amino acid pool. Proteasomes do not handle endocytosed material or whole organelles, peroxisomes do not digest ribosomes, and expelling organelles would not recycle anything.`,
  },
  [r`Prolonged, unresolvable ER stress drives apoptosis largely through induction of the transcription factor {{c1::CHOP}}.`]: {
    question: r`Cells engineered to lack the transcription factor CHOP are exposed to a drug that causes severe ER stress that cannot be resolved. How do they compare with normal cells given the same drug?`,
    options: [r`They die sooner, because the UPR never switches on`, r`They die sooner, because Bcl-2 is not repressed`, r`They survive longer, because Bcl-2 is not repressed`, r`They survive longer, because PERK is never activated`],
    correctAnswer: 2,
    explanation: r`CHOP is the link between unresolved ER stress and apoptosis: it represses the anti-apoptotic protein Bcl-2 and turns on pro-apoptotic genes. Without CHOP, Bcl-2 stays high and death is delayed. PERK and the rest of the unfolded protein response still activate upstream of CHOP, and keeping Bcl-2 protects cells instead of killing them.`,
  },
  [r`How does the calnexin/calreticulin cycle enforce glycoprotein quality control?`]: {
    question: r`A newly made glycoprotein in the ER lumen has had its N-linked glycan trimmed until exactly one glucose remains. What happens to the protein next?`,
    options: [r`It binds the KDEL receptor and is locked in the ER`, r`It binds calnexin or calreticulin for a folding attempt`, r`It is sent back to the cytosol for proteasomal decay`, r`It leaves at once for the Golgi as a folded protein`],
    correctAnswer: 1,
    explanation: r`A single remaining glucose is the signal that lets the glycoprotein bind calnexin or calreticulin, which hold it for folding. Export to the Golgi comes only after the last glucose is removed and folding is judged correct, and degradation is reserved for proteins that fail repeated rounds. KDEL receptors retrieve ER residents from the Golgi and do not read glucose.`,
  },
  [r`Name two synthetic (anabolic) contributions of peroxisomes.`]: {
    question: r`A patient's peroxisomes oxidize fatty acids normally but lack the enzymes that begin ether phospholipid synthesis. Which finding is expected?`,
    options: [r`Demyelination, because sphingomyelin accumulates`, r`Hemolysis, because NADPH cannot be regenerated`, r`Demyelination, because plasmalogens are deficient`, r`Muscle cramps, because glycogen cannot be cleaved`],
    correctAnswer: 2,
    explanation: r`Peroxisomes start the synthesis of plasmalogens, ether phospholipids that are abundant in myelin, so losing this anabolic role damages myelin. Sphingomyelin buildup is a lysosomal problem, glycogen breakdown is cytosolic, and NADPH regeneration belongs to the pentose phosphate pathway.`,
  },
  [r`What fails in Zellweger syndrome?`]: {
    question: r`Fibroblasts from an infant with a PEX gene mutation are stained with an antibody against catalase. Where is the catalase found?`,
    options: [r`Outside the cell, because it enters the ER by default`, r`Nowhere, because its gene is no longer transcribed`, r`Concentrated inside normal-looking peroxisomes`, r`Spread through the cytosol, outside empty peroxisomes`],
    correctAnswer: 3,
    explanation: r`Peroxins are the import machinery for peroxisomal matrix proteins, so in Zellweger syndrome the enzymes are still made on free ribosomes but stay in the cytosol while the peroxisomes remain empty ghosts. The catalase gene is intact, and a protein with no ER signal sequence never enters the secretory pathway.`,
  },
  [r`Why are mitochondrial DNA diseases maternally inherited?`]: {
    question: r`A woman whose cells all carry a disease-causing mitochondrial DNA mutation has two sons and two daughters with an unaffected man. All four later have children with unaffected partners. Which grandchildren can inherit the mutation?`,
    options: [r`The children of all four offspring`, r`Only the children of her daughters`, r`Only the children of her sons`, r`Only the sons of her daughters`],
    correctAnswer: 1,
    explanation: r`Mitochondria come from the oocyte, so all four of her children carry the mutation, but only the daughters pass it on, and they pass it to sons and daughters alike. Her sons' sperm mitochondria are destroyed after fertilization, so their children are not at risk. Limiting it to daughters' sons confuses this with X-linked inheritance.`,
  },
  [r`Endosymbiosis evidence: mitochondria have double membranes, {{c1::70S-like ribosomes}}, circular DNA, and replicate by {{c2::fission}}.`]: {
    question: r`Cycloheximide blocks only eukaryotic cytosolic 80S ribosomes, and chloramphenicol blocks only bacterial-type ribosomes. Human cells are given labeled amino acids, and the proteins encoded by mitochondrial DNA are examined. What is seen?`,
    options: [r`Labeling continues with cycloheximide but stops with chloramphenicol`, r`Labeling stops with either drug, since both ribosome types are needed`, r`Labeling continues with chloramphenicol but stops with cycloheximide`, r`Labeling continues with either drug, since neither ribosome is needed`],
    correctAnswer: 0,
    explanation: r`Mitochondria translate their own genes on bacterial-style (70S-like) ribosomes inside the matrix, so chloramphenicol stops that synthesis and cycloheximide does not. The reversed choice treats mitochondrial ribosomes as 80S, and the last two ignore that these proteins are made by one ribosome type only.`,
  },
  [r`Match mitochondrial compartments to contents: matrix vs intermembrane space.`]: {
    question: r`A researcher gently ruptures only the outer membrane of isolated mitochondria, leaving the inner membrane intact, and collects the soluble material that escapes. What does that material contain?`,
    options: [r`Cytochrome c, but not the citric acid cycle enzymes`, r`Mitochondrial ribosomes along with cytochrome c`, r`Citric acid cycle enzymes, but not cytochrome c`, r`Mitochondrial DNA, but not the cytochrome c pool`],
    correctAnswer: 0,
    explanation: r`Breaking only the outer membrane releases the intermembrane space, which holds cytochrome c. The citric acid cycle enzymes, mitochondrial DNA and mitochondrial ribosomes are all in the matrix, still sealed behind the intact inner membrane.`,
  },
  [r`What determines whether a ribosome ends up free in the cytosol or bound to the ER?`]: {
    question: r`Ribosomes are collected separately from the rough ER and from the cytosol, stripped of their mRNA, and each set is then given the same mRNA for a cytosolic enzyme in an extract that contains ER membranes. What happens?`,
    options: [r`The formerly bound set returns to the ER to make it`, r`Neither set translates it without an ER signal`, r`Only the formerly free set is able to translate it`, r`Both sets translate it while free in the cytosol`],
    correctAnswer: 3,
    explanation: r`Ribosomes are one interchangeable pool, and only the nascent chain decides location: with no signal sequence, any ribosome stays free. The other choices assume that ER ribosomes are a permanently different kind or that a signal sequence is needed for translation itself.`,
  },
  [r`How is a protein marked for proteasomal degradation, and which linkage is decisive?`]: {
    question: r`Cells express only a mutant ubiquitin in which lysine 48 is replaced by arginine. The mutant is activated by E1 and attached to target proteins normally. What happens to a normally short-lived cyclin?`,
    options: [r`It is degraded faster, because E3 ligases lose specificity`, r`It is rerouted to lysosomes, because E2 cannot bind to it`, r`It is stabilized, because Lys48-linked chains cannot form`, r`It is degraded as usual, because one ubiquitin is enough`],
    correctAnswer: 2,
    explanation: r`The proteasome recognizes a chain of at least four ubiquitins joined through Lys48, so without that lysine the chain cannot be built and the cyclin persists. A single ubiquitin is not a degradation signal, E3 specificity lies in the ligase and not in Lys48, and the mutation does not send the protein to lysosomes.`,
  },
  [r`Define heteroplasmy and the threshold effect in mitochondrial disease.`]: {
    question: r`A mildly affected mother has 30% mutant mitochondrial DNA in her cells. One of her children is severely affected and another is healthy. What best explains the difference?`,
    options: [r`Random X-inactivation silenced the mutant allele in one child`, r`Random segregation gave their oocytes unequal mutant fractions`, r`Incomplete dominance gave their nuclei unequal allele doses`, r`Paternal mitochondria diluted the mutant fraction in one child`],
    correctAnswer: 1,
    explanation: r`In heteroplasmy, mutant and normal mtDNA are divided at random, so different oocytes receive different mutant fractions and only a child above the tissue threshold shows disease. Mitochondrial DNA is not on the X chromosome or in the nucleus, and the father's mitochondria are destroyed and contribute nothing.`,
  },
  [r`How are nucleus-encoded proteins imported into the mitochondrial matrix?`]: {
    question: r`Cells are treated with an uncoupler that collapses the electrical potential across the inner mitochondrial membrane. What happens to a newly made precursor of a matrix enzyme?`,
    options: [r`It stays inside the ER lumen with its presequence cleaved`, r`It enters the matrix but keeps its presequence uncleaved`, r`It enters the matrix faster and its presequence is cleaved`, r`It stays outside the matrix with its presequence uncleaved`],
    correctAnswer: 3,
    explanation: r`The membrane potential pulls the positively charged presequence through TIM23, so without it import into the matrix fails, and the matrix peptidase never meets the presequence. Entry without the potential is not possible, and a mitochondrial presequence does not direct a protein into the ER.`,
  },
  [r`Nuclear pore complexes permit passive diffusion only below roughly {{c1::40 kDa}}; larger cargo requires signal-mediated transport.`]: {
    question: r`Two inert fluorescent dextrans with no targeting signals, one of 10 kDa and one of 150 kDa, are injected into the cytosol of a cell. What is seen an hour later?`,
    options: [r`Only the 10 kDa dextran is found in the nucleus`, r`Both dextrans are found throughout the nucleus`, r`Neither dextran is found inside the nucleus`, r`Only the 150 kDa dextran is found in the nucleus`],
    correctAnswer: 0,
    explanation: r`Nuclear pores allow passive diffusion only up to roughly 40 kDa, so the 10 kDa dextran enters and the 150 kDa dextran is excluded because it has no signal for carrier-mediated transport. Saying both enter ignores the size limit, and saying neither enters ignores that small molecules pass freely.`,
  },
  [r`Peroxisomal matrix proteins carry the C-terminal tripeptide {{c1::Ser-Lys-Leu (SKL)}} and are imported {{c2::already folded}}.`]: {
    question: r`A peroxisomal enzyme subunit that lacks its Ser-Lys-Leu ending forms a stable dimer in the cytosol with a normal subunit that has the ending. Where does the subunit without the signal end up?`,
    options: [r`In the ER lumen, as SRP binds the partner's signal`, r`In the peroxisome, carried in within the folded dimer`, r`In the cytosol, as each chain must enter unfolded`, r`In the peroxisome, after its signal peptide is cut off`],
    correctAnswer: 1,
    explanation: r`Peroxisomes import fully folded and even oligomeric proteins, so a subunit with no SKL signal can ride in with a partner that has one. The cytosol choice applies the unfolded threading rule of the ER and mitochondria, the SKL signal is C-terminal and is not cut off, and SRP reads hydrophobic N-terminal ER signals, not SKL.`,
  },
  [r`Human mtDNA is a {{c1::circular}} genome encoding {{c2::13}} proteins plus 22 tRNAs and 2 rRNAs.`]: {
    question: r`A cultured human cell line has lost all of its mitochondrial DNA. Which statement describes its mitochondria?`,
    options: [r`They work normally, since mtDNA encodes only RNA molecules`, r`They vanish, since mtDNA encodes all mitochondrial proteins`, r`They persist but lack every enzyme of the citric acid cycle`, r`They persist but lack 13 oxidative phosphorylation subunits`],
    correctAnswer: 3,
    explanation: r`Human mtDNA encodes just 13 proteins, all subunits of oxidative phosphorylation, so the organelles remain but cannot run the complete chain. The roughly 1,500 other mitochondrial proteins, including the citric acid cycle enzymes, are nuclear-encoded and still imported, and mtDNA encodes proteins as well as tRNAs and rRNAs.`,
  },
  [r`What do mitochondrial fusion and fission each accomplish?`]: {
    question: r`Cells are engineered to lack Drp1. What do their mitochondria look like, and what can they no longer do?`,
    options: [r`Many small fragments that cannot be removed by mitophagy`, r`A fused, elongated network that cannot shed damaged segments`, r`A fused, elongated network that cannot mix matrix contents`, r`Many small fragments that cannot share their mtDNA copies`],
    correctAnswer: 1,
    explanation: r`Drp1 drives fission, so without it fusion goes unopposed and the mitochondria form a long connected network that cannot split off damaged pieces for mitophagy or divide for cell division. Small fragments that cannot share contents describe a loss of fusion (mitofusins or OPA1), and a fused network mixes its contents well.`,
  },
  [r`What is macroautophagy, and how is it switched on by starvation?`]: {
    question: r`Cells lacking a functional ULK1 complex are deprived of nutrients. What is observed?`,
    options: [r`mTORC1 is inhibited, but no autophagosomes form`, r`mTORC1 is inhibited, and autophagosomes form`, r`mTORC1 stays active, yet autophagosomes form`, r`mTORC1 stays active, so no autophagosomes form`],
    correctAnswer: 0,
    explanation: r`Starvation still shuts off mTORC1, but autophagosome formation needs the ULK1 initiation complex that mTORC1 normally holds in check, so the signal has nothing to act on. Choices with active mTORC1 ignore that starvation inhibits it, and normal autophagosome formation ignores that ULK1 is the required next step.`,
  },
  [r`Vesicle coats: {{c1::COPII}} carries ER-to-Golgi cargo, {{c2::COPI}} runs Golgi-to-ER retrograde, and clathrin serves endocytosis plus trans-Golgi exit.`]: {
    question: r`Vesicles from a pancreatic beta cell are sorted by their protein coat. Which population carries newly made proinsulin on its first step out of the ER?`,
    options: [r`COPII vesicles, the coat for ER-to-Golgi transport`, r`COPII vesicles, the coat for Golgi-to-ER retrieval`, r`Clathrin vesicles, the coat for ER-to-Golgi transport`, r`COPI vesicles, the coat for ER-to-Golgi transport`],
    correctAnswer: 0,
    explanation: r`COPII coats the forward vesicles that bud from the ER toward the Golgi. COPI works in the opposite direction, returning escaped proteins from the Golgi to the ER, and clathrin coats endocytic vesicles and carriers leaving the trans-Golgi, not vesicles leaving the ER.`,
  },
  [r`Peroxisomes perform {{c1::beta-oxidation of very-long-chain fatty acids}} and destroy the resulting H2O2 with {{c2::catalase}}.`]: {
    question: r`Cells whose catalase has been inhibited are fed a 26-carbon fatty acid. What builds up inside their peroxisomes, and why?`,
    options: [r`Superoxide, because catalase passes electrons to water`, r`Hydrogen peroxide, because oxidases pass electrons to O₂`, r`Lactic acid, because pyruvate takes electrons from NADH`, r`Hydrogen peroxide, because the ETC pumps protons outward`],
    correctAnswer: 1,
    explanation: r`Peroxisomal beta-oxidation of very-long-chain fatty acids hands electrons directly to O₂, producing H₂O₂ that catalase would normally convert to water and oxygen. Lactate formation is cytosolic, the electron transport chain is mitochondrial and not peroxisomal, and catalase destroys peroxide instead of making superoxide.`,
  },
  [r`The {{c1::signal recognition particle (SRP)}} binds a nascent signal sequence, pauses translation, and docks the ribosome at the ER's {{c2::SRP receptor}}.`]: {
    question: r`A cell line has normal SRP but lacks functional SRP receptor in its ER membrane. Where are ribosomes that have begun translating a secretory protein found?`,
    options: [r`In the cytosol, translating quickly with no SRP bound`, r`On the Golgi, docked by SRP at the cis face membrane`, r`In the cytosol, paused with SRP on the signal sequence`, r`On the ER, feeding the chain into the Sec61 translocon`],
    correctAnswer: 2,
    explanation: r`SRP binds the emerging signal sequence and pauses translation until it meets the SRP receptor on the ER, so without the receptor the complexes stay stalled in the cytosol. Reaching the translocon requires docking through the receptor, SRP still binds because it is normal, and SRP never targets ribosomes to the Golgi.`,
  },
  [r`Which organelles import their proteins post-translationally, and what does mitochondrial import specifically require in the cytosol?`]: {
    question: r`A drug inactivates the Hsp70 chaperones of the cytosol. Protein import into which organelle is most directly impaired, and why?`,
    options: [r`Peroxisomes, since cargo must stay unfolded to bind to Pex5`, r`Mitochondria, since precursors must stay unfolded for TOM and TIM`, r`Mitochondria, since precursors must fold before entering TOM`, r`The nucleus, since cargo must stay unfolded to cross the pores`],
    correctAnswer: 1,
    explanation: r`Mitochondrial precursors are finished in the cytosol and must be held unfolded by cytosolic Hsp70 so they can thread through the TOM and TIM channels. The nucleus and peroxisomes import folded proteins, so they do not need this, and a folded precursor cannot pass through TOM.`,
  },
  [r`Nuclear localization signals are short stretches rich in {{c1::basic residues (Lys/Arg)}}, are never cleaved, and are read by {{c2::importins}}.`]: {
    question: r`A nuclear protein is spread through the cytoplasm when the nuclear envelope breaks down in mitosis. After the envelope reforms, can the same protein molecules return to the nucleus?`,
    options: [r`Yes, since the NLS is never cleaved and importins bind it again`, r`Yes, since proteins of any size diffuse freely through the pores`, r`No, since importins read only hydrophobic N-terminal signals`, r`No, since the NLS was cleaved by a peptidase on the first entry`],
    correctAnswer: 0,
    explanation: r`A nuclear localization signal is a stretch of basic residues that stays on the protein, so importins can carry it in again after every mitosis. Cleavage on entry and a hydrophobic N-terminal signal describe the ER signal sequence, and free diffusion through pores is limited to small molecules.`,
  },
  [r`Lysosomal hydrolases are tagged with {{c1::mannose-6-phosphate}} in the cis-Golgi and sorted by M6P receptors in the {{c2::trans}}-Golgi network.`]: {
    question: r`A cell line has a normal GlcNAc phosphotransferase but makes no mannose-6-phosphate receptors. What happens to its newly made lysosomal hydrolases?`,
    options: [r`They are left untagged and retained in the ER`, r`They are tagged with M6P and delivered to lysosomes`, r`They are tagged with M6P but secreted from the cell`, r`They are left untagged and secreted from the cell`],
    correctAnswer: 2,
    explanation: r`Tagging in the cis-Golgi still occurs, but sorting in the trans-Golgi network needs the M6P receptor, so the tagged enzymes follow the default route out of the cell. Untagged enzymes describe a phosphotransferase defect instead, and delivery to lysosomes cannot happen with no receptor to capture the tag.`,
  },
  [r`What happens to the ER signal sequence once translocation begins, and how do membrane proteins differ?`]: {
    question: r`A protein has no cleavable N-terminal signal but contains an internal hydrophobic signal-anchor sequence. What is the fate of that sequence after the protein is made on the rough ER?`,
    options: [r`It stays uncleaved, embedded as a transmembrane segment`, r`It is cut off by signal peptidase and then broken down`, r`It is cut off, and the protein remains in the cytosol`, r`It stays uncleaved, and the whole protein is secreted`],
    correctAnswer: 0,
    explanation: r`Internal signal-anchor sequences are not cleaved: they target the ribosome to the ER and then remain in the bilayer as the membrane-spanning segment. Removal by signal peptidase is the fate of N-terminal signals on secreted proteins, and a protein anchored in the membrane is neither secreted nor left in the cytosol.`,
  },
  [r`How does the Ran-GTP gradient give nuclear transport its direction?`]: {
    question: r`A mutant Ran that is locked in its GTP-bound form is introduced at a high level into the cytosol of a cell. What happens to importin-cargo complexes?`,
    options: [r`They fall apart only in the nucleus, so import is unchanged`, r`They hold together tightly, so the cargo is imported faster`, r`They pick up exportins in the cytosol, so the cargo is stored`, r`They fall apart in the cytosol, so the cargo is not imported`],
    correctAnswer: 3,
    explanation: r`Ran-GTP makes importins let go of their cargo, which normally happens only inside the nucleus where Ran-GTP is high. Placing Ran-GTP in the cytosol releases cargo on the wrong side, so import fails. The other choices miss that the direction of transport depends on Ran-GTP being confined to the nucleus.`,
  },
  [r`Describe ER-associated degradation (ERAD).`]: {
    question: r`The CFTR channel with the ΔF508 mutation would conduct some chloride if it reached the cell surface, yet almost none is found in the plasma membrane. Why?`,
    options: [r`It is released from the cell because it has lost its membrane anchor`, r`It is moved from the ER to the cytosol and degraded by proteasomes`, r`It is moved from the Golgi to lysosomes and degraded by hydrolases`, r`It is held in the nucleus because its mRNA cannot leave the pores`],
    correctAnswer: 1,
    explanation: r`The misfolded channel is caught by ER quality control, sent back across the ER membrane, polyubiquitinated and destroyed by the 26S proteasome: this is ER-associated degradation. It never reaches the Golgi or lysosomes, it is not secreted, and the defect is in protein folding, not in mRNA export.`,
  },
  [r`Why are hepatocytes and adrenal cortex cells especially rich in smooth ER?`]: {
    question: r`An electron micrograph of a Leydig cell, which makes testosterone, shows one organelle in unusual abundance. Which organelle is it, and why?`,
    options: [r`Rough ER, where testosterone is folded and packaged`, r`Smooth ER, where peptide hormones are glycosylated`, r`Smooth ER, where steroids are built from cholesterol`, r`Rough ER, where steroids are built from amino acids`],
    correctAnswer: 2,
    explanation: r`Steroid-producing cells are packed with smooth ER because its membranes hold the enzymes that convert cholesterol into steroid hormones. Steroids are lipids, not chains of amino acids, so they are not made or folded on rough ER, and glycosylation of peptide hormones is not a smooth ER job.`,
  },
  [r`Why does the M6P receptor release its cargo in the late endosome, and what happens to the receptor afterward?`]: {
    question: r`In a cell whose retromer-coated vesicles cannot form, what happens to mannose-6-phosphate receptors and to newly made lysosomal hydrolases over time?`,
    options: [r`Receptors fail to return to the trans-Golgi, so new hydrolases are secreted`, r`Receptors never release cargo in endosomes, so endosomal pH rises to 7`, r`Receptors fail to leave the trans-Golgi, so new hydrolases stay in the ER`, r`Receptors return to the trans-Golgi faster, so lysosomes gain hydrolases`],
    correctAnswer: 0,
    explanation: r`After the receptor releases its cargo in the acidic late endosome, retromer carries the empty receptor back to the trans-Golgi. Without that return trip the Golgi runs out of receptors, and tagged hydrolases leave by the default secretory route. Cargo release depends on pH, not retromer, and the receptors still leave the Golgi in clathrin-coated vesicles.`,
  },
  [r`The unfolded protein response is initiated by three ER membrane sensors: {{c1::PERK}}, {{c2::IRE1}}, and ATF6.`]: {
    question: r`A misfolding-prone secretory protein is overproduced so that it piles up in the ER lumen. Which set of proteins is activated to start the response?`,
    options: [r`PERK, IRE1 and ATF6 in the Golgi membrane`, r`PERK, IRE1 and ATF6 in the ER membrane`, r`TOM, TIM23 and Hsp70 in the ER membrane`, r`E1, E2 and E3 enzymes in the ER lumen`],
    correctAnswer: 1,
    explanation: r`The unfolded protein response is started by three sensors that span the ER membrane: PERK, IRE1 and ATF6. They sit in the ER, not the Golgi. TOM and TIM23 are mitochondrial import channels, and E1, E2 and E3 are cytosolic enzymes that attach ubiquitin.`,
  },
  [r`How does PERK reduce the ER's folding load during the unfolded protein response?`]: {
    question: r`Cells express a form of eIF2-alpha that cannot be phosphorylated and are then put under ER stress. What is the consequence?`,
    options: [r`Global translation shuts down, so the ER folding load drops fast`, r`ATF4 is translated far more, so chaperone genes are overexpressed`, r`PERK cannot sense the stress, so BiP stays bound to the sensors`, r`Global translation continues, so the ER folding load stays high`],
    correctAnswer: 3,
    explanation: r`PERK lowers the folding load by phosphorylating eIF2-alpha, which blocks translation initiation; if eIF2-alpha cannot be phosphorylated, new proteins keep pouring into the ER. PERK still senses the stress because its activation is upstream, and the rise in ATF4 translation also depends on that phosphorylation.`,
  },
  [r`What is BiP's dual role in the endoplasmic reticulum?`]: {
    question: r`Cells engineered to make a large excess of BiP are given a mild ER stress. How does their unfolded protein response compare with that of normal cells?`,
    options: [r`Weaker, since spare BiP keeps the sensors bound and inactive`, r`The same, since BiP only helps fold proteins in the lumen`, r`Stronger, since spare BiP unfolds more of the client proteins`, r`Stronger, since spare BiP binds the sensors and turns them on`],
    correctAnswer: 0,
    explanation: r`BiP both chaperones unfolded proteins and holds PERK, IRE1 and ATF6 inactive, and the sensors fire only when misfolded proteins pull BiP away. With extra BiP there is enough to cover the misfolded proteins and still keep the sensors silenced. BiP binding inhibits the sensors, and BiP assists folding instead of unfolding proteins.`,
  },
  [r`N-linked glycosylation begins in the {{c1::ER}} with transfer of a preassembled oligosaccharide onto {{c2::asparagine}}; O-linked sugars are added in the Golgi.`]: {
    question: r`A secreted protein has a single Asn-X-Ser motif. Changing that asparagine to glutamine removes one modification. Which modification is lost, and where is it normally added?`,
    options: [r`An O-linked glycan, normally added in the ER`, r`An O-linked glycan, normally added in the Golgi`, r`An N-linked glycan, normally added in the ER`, r`An N-linked glycan, normally added in the Golgi`],
    correctAnswer: 2,
    explanation: r`N-linked glycosylation transfers a preassembled oligosaccharide onto asparagine as the protein enters the ER. O-linked sugars go onto serine or threonine hydroxyl groups, and that happens in the Golgi, so the choices naming O-linkage or placing the N-linked transfer in the Golgi are wrong.`,
  },
  [r`The lysosomal lumen is held at pH {{c1::4.5-5.0}} by the {{c2::V-type H+ ATPase}}.`]: {
    question: r`A lysosome has an internal pH of 5 while the cytosol is near pH 7. How does the H⁺ concentration inside compare with the cytosol, and what maintains the difference?`,
    options: [r`About 2 times higher, kept by an ATP-driven H⁺ pump`, r`About 100 times higher, kept by passive H⁺ channels`, r`About 100 times lower, kept by an ATP-driven H⁺ pump`, r`About 100 times higher, kept by an ATP-driven H⁺ pump`],
    correctAnswer: 3,
    explanation: r`Two pH units is a factor of 10² = 100 in H⁺ concentration, and lower pH means more H⁺, so the lumen is about 100 times more concentrated. Moving protons against that gradient needs the V-type H⁺ ATPase. A factor of 2 treats pH as linear, passive channels would let the gradient run down, and 100 times lower reverses the pH scale.`,
  },
  [r`Why is a small lysosomal leak not immediately catastrophic for the cytosol?`]: {
    question: r`A protease purified from lysosomes is tested at pH 5 and at pH 7.2. What result is expected, and what does it mean for the cell?`,
    options: [r`Inactive at both, so it needs ubiquitin tags to digest a protein`, r`Active at pH 7.2, weak at pH 5, so a small leak does great harm`, r`Active at pH 5, weak at pH 7.2, so a small leak does little harm`, r`Equally active at both, so only the membrane guards the cytosol`],
    correctAnswer: 2,
    explanation: r`Lysosomal hydrolases have pH optima near 5 and lose most of their activity at the neutral pH of the cytosol, which gives the cell a second layer of protection if a little enzyme escapes. The other choices reverse the pH preference, deny any pH dependence, or confuse lysosomal enzymes with the ubiquitin-proteasome system.`,
  },
  [r`State the general logic of a lysosomal storage disease, using Tay-Sachs as the example.`]: {
    question: r`A child lacks a single lysosomal hydrolase that degrades a lipid called S. In the body, S is turned over mainly in heart muscle. What is the expected pattern?`,
    options: [r`S runs short inside lysosomes, mainly in heart muscle`, r`S builds up in the cytosol, equally in every tissue`, r`S builds up inside lysosomes, equally in every tissue`, r`S builds up inside lysosomes, mainly in heart muscle`],
    correctAnswer: 3,
    explanation: r`When one hydrolase is missing, its substrate accumulates in lysosomes, and the damage falls on the cells that turn that substrate over fastest, just as GM2 ganglioside fills neurons in Tay-Sachs disease. The substrate is trapped in lysosomes and not the cytosol, it accumulates instead of running short, and tissues are not affected equally.`,
  },
  [r`In I-cell disease (mucolipidosis II), why do lysosomal enzymes appear in the blood?`]: {
    question: r`Some mannose-6-phosphate receptors sit on the cell surface and bring M6P-tagged proteins in by endocytosis. Fibroblasts from a patient with I-cell disease are grown in medium containing M6P-tagged hydrolases from normal cells. What happens?`,
    options: [r`Their lysosomes stay deficient, since their M6P receptors are absent`, r`Their lysosomes are corrected, since phosphotransferase is restored`, r`Their lysosomes are corrected, since their M6P receptors are normal`, r`Their lysosomes stay deficient, since the tag is removed in the medium`],
    correctAnswer: 2,
    explanation: r`I-cell disease is a failure to add the mannose-6-phosphate tag, not a receptor defect, so the cells can capture already tagged enzymes and deliver them to lysosomes. The patient's own phosphotransferase is still missing, and nothing in the medium strips the tag from the supplied enzymes.`,
  },
  [r`How does the KDEL sequence keep soluble resident proteins in the ER despite constant vesicular traffic?`]: {
    question: r`A normally secreted hormone is engineered to end in the sequence Lys-Asp-Glu-Leu (KDEL). Where is most of the hormone now found, and why?`,
    options: [r`In the ER, retrieved from the Golgi each time it escapes`, r`Outside the cell, since KDEL speeds up exocytosis`, r`In lysosomes, sorted there by the KDEL receptor`, r`In the ER, since it can no longer enter any vesicle`],
    correctAnswer: 0,
    explanation: r`KDEL does not stop a protein from leaving the ER; KDEL receptors in the Golgi capture escaped proteins and return them in COPI vesicles, so the hormone ends up concentrated in the ER. The receptor sends cargo back to the ER, not to lysosomes, and KDEL is a retrieval signal, not a secretion signal.`,
  },
  [r`Early endosomes sit near pH {{c1::6.5}} and recycle receptors, while late endosomes acidify toward pH {{c2::5.5}} and commit cargo to lysosomes.`]: {
    question: r`A pH-sensitive dye attached to an endocytosed ligand reads pH 6.5 five minutes after uptake and pH 5.5 twenty minutes after uptake. Which compartments is the ligand in at those times?`,
    options: [r`A late endosome at 5 min; an early endosome at 20 min`, r`An early endosome at 5 min; a lysosome at 20 min`, r`An early endosome at 5 min; a late endosome at 20 min`, r`A coated pit at 5 min; an early endosome at 20 min`],
    correctAnswer: 2,
    explanation: r`Endosomes acidify as they mature: early endosomes are near pH 6.5 and late endosomes near pH 5.5. A lysosome would read lower still, about 4.5 to 5.0, and a coated pit is open to the extracellular fluid at about pH 7.4. The reversed order runs the acidification backward.`,
  },
  [r`Why does phenobarbital treatment enlarge hepatocyte smooth ER, and what is the clinical consequence?`]: {
    question: r`A patient on a steady dose of a drug that is cleared by liver cytochrome P450 enzymes begins taking phenobarbital. Weeks later, what has happened to the first drug's effect, and why?`,
    options: [r`It falls, since shrunken smooth ER traps the drug inside`, r`It rises, since phenobarbital blocks the P450 enzymes`, r`It rises, since induced P450 enzymes clear the drug slower`, r`It falls, since induced P450 enzymes clear the drug faster`],
    correctAnswer: 3,
    explanation: r`Phenobarbital induces P450 enzymes and the smooth ER expands to house them, so other drugs handled by those enzymes are metabolized faster and their effect drops. Induction speeds clearance instead of slowing it, phenobarbital is an inducer and not an inhibitor here, and the smooth ER grows instead of shrinking.`,
  },
  [r`Palade pulse-labeled pancreatic acinar cells with radioactive amino acids. Where did label appear over time, and what did that prove?`]: {
    question: r`Pancreatic acinar cells are given radioactive amino acids for 3 minutes and then unlabeled amino acids. Autoradiographs are made immediately and again 2 hours later. Where is the label concentrated?`,
    options: [r`Over the rough ER at first, then over secretory granules`, r`Over secretory granules at first, then over the rough ER`, r`Over the Golgi stacks at first, then over the rough ER`, r`Over the rough ER at first, then over the cell nucleus`],
    correctAnswer: 0,
    explanation: r`The brief pulse labels only proteins being synthesized, which is on the rough ER, and the chase shows that cohort moving through the Golgi into secretory granules. Any order ending at the rough ER runs the pathway backward, and secretory proteins never travel to the nucleus.`,
  },
  [r`The GTPase {{c1::dynamin}} assembles as a collar around the neck of a clathrin-coated pit and pinches the vesicle free of the membrane.`]: {
    question: r`Cells expressing a dynamin that binds GTP but cannot hydrolyze it are given a ligand that enters by receptor-mediated endocytosis. What does electron microscopy show at the cell surface?`,
    options: [r`Smooth membrane, since receptors cannot bind the ligand`, r`No coated pits, since clathrin cannot reach the membrane`, r`Free coated vesicles that cannot shed their clathrin`, r`Deep coated pits still joined to the membrane by a neck`],
    correctAnswer: 3,
    explanation: r`Dynamin forms a collar at the neck of a coated pit and uses GTP hydrolysis to pinch the vesicle off, so without hydrolysis the pits invaginate fully but stay attached. Clathrin assembly and ligand binding happen before dynamin acts, and uncoating is a later step that needs the vesicle to be free first.`,
  },
  [r`Distinguish constitutive from regulated secretion, and give a cell that depends on each.`]: {
    question: r`The Ca²⁺ channels of a pancreatic beta cell are blocked. The same cell also releases extracellular matrix proteins by the constitutive pathway. What happens to the two kinds of secretion when glucose rises?`,
    options: [r`Insulin release continues; constitutive secretion stops`, r`Insulin release stops; constitutive secretion continues`, r`Insulin release and constitutive secretion both continue`, r`Insulin release and constitutive secretion both stop`],
    correctAnswer: 1,
    explanation: r`Insulin is stored in dense granules that fuse only when a Ca²⁺ signal arrives, so blocking Ca²⁺ entry stops regulated release. Constitutive vesicles fuse continuously with no trigger, so that pathway carries on. The other choices treat both pathways as needing, or not needing, the Ca²⁺ signal.`,
  },
  [r`The proteasome and the lysosome both destroy proteins. Give three ways they differ.`]: {
    question: r`A weak base is used to raise the pH inside the lysosomes of a cell to 7. The cell contains a ubiquitin-tagged cytosolic regulator and an endocytosed foreign protein. Whose degradation is blocked?`,
    options: [r`Neither, since both proteins are degraded after ubiquitin tagging`, r`Both, since proteasomes sit inside the membrane of the lysosome`, r`Only the endocytosed protein's, since proteasomes work at neutral pH`, r`Only the tagged regulator's, since proteasomes need an acidic lumen`],
    correctAnswer: 2,
    explanation: r`Endocytosed cargo is digested by lysosomal acid hydrolases, which fail at pH 7, while the ubiquitin-tagged regulator goes to the proteasome, a membrane-free cytosolic complex that works at neutral pH. The other choices give the proteasome an acidic or lysosomal location or send endocytosed cargo to the proteasome.`,
  },
  [r`Golgi processing is polarized: mannose is phosphorylated in the {{c1::cis}} cisternae, while galactose and sialic acid are added in the {{c2::trans}} cisternae.`]: {
    question: r`In a mutant cell line the enzymes of the trans Golgi cisternae are inactive, while the ER and the cis Golgi work normally. What is wrong with the glycoproteins this cell produces?`,
    options: [r`Terminal galactose and sialic acid are missing`, r`Disulfide bonds formed in the ER are missing`, r`The core N-linked oligosaccharide is missing`, r`Mannose phosphate tags on hydrolases are missing`],
    correctAnswer: 0,
    explanation: r`Golgi processing is ordered by compartment, and galactose and sialic acid are the late additions made in the trans cisternae. Mannose is phosphorylated in the cis cisternae, and the N-linked core and disulfide bonds are both put on in the ER, so those steps are unaffected.`,
  },
  [r`A familial hypercholesterolemia allele encodes a receptor that binds LDL normally but is never internalized. What is defective?`]: {
    question: r`A transferrin receptor is engineered without its cytoplasmic tail, while its extracellular and membrane-spanning parts are unchanged. How does the receptor behave?`,
    options: [r`It never reaches the surface, as it lacks a signal peptide`, r`It binds transferrin at the surface but is not internalized`, r`It cannot bind transferrin but is internalized as normal`, r`It binds transferrin and is internalized faster than normal`],
    correctAnswer: 1,
    explanation: r`Ligand binding uses the extracellular domain, but clustering into clathrin-coated pits requires a sorting signal in the cytoplasmic tail that adaptor proteins read. Without the tail the receptor binds its ligand and stays at the surface. The tail does not contain the ER signal sequence, so delivery to the surface is unaffected.`,
  },
  [r`A secreted protein's gene is altered to delete its N-terminal signal sequence. Where does the protein end up, and why?`]: {
    question: r`The gene for a lysosomal hydrolase is altered so that the enzyme lacks its N-terminal ER signal sequence. Where does the enzyme end up?`,
    options: [r`In the ER lumen, held back for lack of a signal`, r`Outside the cell, by the default secretory route`, r`In the cytosol, made entirely on free ribosomes`, r`In lysosomes, since its M6P patch is still intact`],
    correctAnswer: 2,
    explanation: r`Without a signal sequence SRP never binds, the ribosome never docks at the ER, and the protein is finished in the cytosol. Mannose-6-phosphate tagging and default secretion both happen only after a protein has entered the ER, so neither route is open to it, and it cannot be retained in a compartment it never entered.`,
  },
  [r`Tay-Sachs and Niemann-Pick both show a cherry-red macula, but only {{c1::Niemann-Pick}} adds hepatosplenomegaly.`]: {
    question: r`Two infants have progressive neurodegeneration and a cherry-red macula. Infant 1 has a normal abdomen; infant 2 has an enlarged liver and spleen. Which diagnoses fit, and which enzyme does infant 2 lack?`,
    options: [r`Infant 1 Niemann-Pick; infant 2 Tay-Sachs, lacking hexosaminidase A`, r`Infant 1 Tay-Sachs; infant 2 Niemann-Pick, lacking sphingomyelinase`, r`Infant 1 Niemann-Pick; infant 2 Tay-Sachs, lacking sphingomyelinase`, r`Infant 1 Tay-Sachs; infant 2 Niemann-Pick, lacking hexosaminidase A`],
    correctAnswer: 1,
    explanation: r`Both diseases give a cherry-red macula, but only Niemann-Pick adds hepatosplenomegaly, because sphingomyelin is stored in reticuloendothelial organs as well as neurons when sphingomyelinase is missing. Tay-Sachs lacks hexosaminidase A and has no organ enlargement, so the choices that swap the diseases or the enzymes are wrong.`,
  },
  [r`Vesicle fusion requires a v-SNARE pairing with a t-SNARE; {{c1::botulinum and tetanus}} toxins are proteases that cleave these SNARE proteins.`]: {
    question: r`A motor nerve terminal is poisoned with botulinum toxin. An action potential arrives and Ca²⁺ enters the terminal normally. What happens next?`,
    options: [r`Vesicles cannot fuse, so no acetylcholine is released`, r`Vesicles fuse normally, but the receptors are blocked`, r`Vesicles fuse nonstop, so acetylcholine floods out`, r`Vesicles cannot form, so no acetylcholine is stored`],
    correctAnswer: 0,
    explanation: r`Botulinum toxin is a protease that cuts SNARE proteins, and without v-SNARE and t-SNARE pairing the synaptic vesicles cannot fuse with the membrane, which causes flaccid paralysis. The toxin does not stop vesicles from being made or filled, does not act on the postsynaptic receptors, and blocks release instead of increasing it.`,
  },
  [r`Chloroquine and ammonium chloride are weak bases that accumulate in lysosomes and {{c1::raise the internal pH}}, inactivating acid hydrolases.`]: {
    question: r`Cells are treated with ammonium chloride, a weak base that collects in acidic compartments, and are then given LDL. What happens to the LDL and its receptor after endocytosis?`,
    options: [r`LDL is digested faster, since hydrolases prefer a neutral pH`, r`LDL stays bound to its receptor, so receptor recycling stalls`, r`LDL cannot bind at the surface, so endocytosis never starts`, r`LDL is released sooner, so receptor recycling speeds up`],
    correctAnswer: 1,
    explanation: r`Weak bases raise the pH of endosomes and lysosomes, and it is low pH that makes receptors let go of their ligands, so LDL stays on its receptor and the receptor is not recycled. Binding at the neutral cell surface is unaffected, and acid hydrolases lose activity as pH rises, so digestion slows.`,
  },
  [r`Gaucher disease, the most common lysosomal storage disease, comes from deficient {{c1::glucocerebrosidase}}, loading macrophages with glucocerebroside.`]: {
    question: r`A 30-year-old man has bone pain crises, low blood cell counts and a massively enlarged spleen, with normal intellect and a normal retina. His marrow macrophages have cytoplasm that looks like crumpled tissue paper. Which enzyme infusion treats him?`,
    options: [r`Sphingomyelinase, to clear stored sphingomyelin`, r`Alpha-L-iduronidase, to clear stored dermatan sulfate`, r`Glucocerebrosidase, to clear stored glucocerebroside`, r`Hexosaminidase A, to clear stored GM2 ganglioside`],
    correctAnswer: 2,
    explanation: r`Lipid-laden macrophages with a crumpled-tissue-paper look, bone crises, pancytopenia and a big spleen describe Gaucher disease, which is deficient glucocerebrosidase and is treated by replacing that enzyme. Hexosaminidase A and sphingomyelinase deficiencies cause neurodegeneration with a cherry-red macula, and iduronidase deficiency is a mucopolysaccharidosis with coarse facial features.`,
  },
  [r`Fabry disease breaks the usual inheritance pattern of lysosomal storage diseases. How, and what accumulates?`]: {
    question: r`A woman's brother and her mother's brother both have burning pain in the hands and feet, small dark red skin spots and failing kidneys. Her parents are healthy. What is the inheritance pattern and the deficient enzyme?`,
    options: [r`Autosomal recessive; alpha-galactosidase A is deficient`, r`Autosomal recessive; glucocerebrosidase is deficient`, r`X-linked recessive; alpha-galactosidase A is deficient`, r`X-linked recessive; hexosaminidase A is deficient`],
    correctAnswer: 2,
    explanation: r`Neuropathic pain, angiokeratomas and renal failure in males related through unaffected women is Fabry disease, which is X-linked recessive and due to deficient alpha-galactosidase A. Most other lysosomal storage diseases are autosomal recessive, which is the pattern Fabry breaks, and the hexosaminidase and glucocerebrosidase deficiencies belong to Tay-Sachs and Gaucher disease.`,
  },
  [r`Hurler and Hunter syndromes both store mucopolysaccharides. Which two features separate them?`]: {
    question: r`A boy has coarse facial features, an enlarged liver and spleen, and developmental delay. His corneas are clear, and his mother's brother had the same condition. Which diagnosis and enzyme deficiency fit?`,
    options: [r`Hunter syndrome, from iduronate sulfatase deficiency`, r`Hunter syndrome, from alpha-L-iduronidase deficiency`, r`Hurler syndrome, from iduronate sulfatase deficiency`, r`Hurler syndrome, from alpha-L-iduronidase deficiency`],
    correctAnswer: 0,
    explanation: r`Clear corneas and transmission through the maternal line to males point to Hunter syndrome, which is X-linked recessive and caused by iduronate sulfatase deficiency. Hurler syndrome is autosomal recessive, clouds the cornea and lacks alpha-L-iduronidase, so the choices naming Hurler or pairing Hunter with iduronidase are wrong.`,
  },
  [r`Pompe disease traps glycogen inside {{c1::lysosomes}} because acid maltase is missing, while McArdle disease blocks {{c2::cytosolic}} glycogen breakdown.`]: {
    question: r`A teenager gets muscle cramps early in exercise, and his blood lactate fails to rise during exertion. His heart is normal. On muscle biopsy, where is the excess glycogen, and which disease is this?`,
    options: [r`Inside lysosomes, as in Pompe disease`, r`Free in the cytosol, as in Pompe disease`, r`Free in the cytosol, as in McArdle disease`, r`Inside lysosomes, as in McArdle disease`],
    correctAnswer: 2,
    explanation: r`Exercise intolerance with a flat lactate curve is McArdle disease, a block in cytosolic glycogen breakdown, so glycogen builds up in the cytosol. Pompe disease traps glycogen inside lysosomes because acid maltase is missing and shows up in infancy with an enlarged heart and weak muscle tone, which this patient lacks.`,
  },
  [r`Brefeldin A makes the Golgi disperse and its contents redistribute into the ER. Which step is blocked?`]: {
    question: r`Liver cells that secrete albumin are treated with brefeldin A. What happens to albumin secretion and to the resident enzymes of the Golgi?`,
    options: [r`Secretion stops, and the Golgi enzymes appear in the ER`, r`Secretion stops, and the Golgi enzymes appear in lysosomes`, r`Secretion continues, and the Golgi enzymes appear in the ER`, r`Secretion speeds up, and the ER enzymes appear in the Golgi`],
    correctAnswer: 0,
    explanation: r`Brefeldin A blocks the coat assembly needed for forward ER-to-Golgi transport while retrograde flow goes on, so secretion halts and Golgi contents drain back into the ER. Secretion cannot continue without forward traffic, the Golgi contents move to the ER and not to lysosomes, and the net flow is backward, not forward.`,
  },
}
